component_data_script:
rows = props.get("facts") or []
if isinstance(rows, str):
	try:
		rows = json.loads(rows)
	except Exception:
		rows = [line for line in rows.split("\n") if line.strip()]
if not isinstance(rows, list):
	rows = []

facts = []
for raw in rows:
	parts = [part.strip() for part in str(raw).split("|", 1)]
	if not parts or not parts[0]:
		continue
	facts.append({"term": parts[0], "detail": parts[1] if len(parts) > 1 else ""})
layout = str(props.get("layout") or "stack")
if layout not in ["stack", "pair", "rows"]:
	layout = "stack"
component.facts = facts
component.layout = layout
